installer-gui-script.script:
// Catch the wrong download before anything is installed, and say which one to get.
function rightMac() {
    var appleSilicon = system.sysctl('hw.optional.arm64') == 1;
    if ('@ARCH@' == 'mac-apple-silicon' && !appleSilicon) {
        my.result.type = 'Fatal';
        my.result.title = 'This Mac needs the Intel download';
        my.result.message = 'This installer is for Macs with Apple silicon (M1 and newer). ' +
            'Download "Limitless-Sound-Suite-mac-intel" from chittychitty38.github.io/Limitless-sound instead.';
        return false;
    }
    if ('@ARCH@' == 'mac-intel' && appleSilicon) {
        my.result.type = 'Warning';
        my.result.title = 'There is a faster version for this Mac';
        my.result.message = 'This installer is for Intel Macs. It works on this Mac too, but the Apple silicon ' +
            'download runs faster. Get it from chittychitty38.github.io/Limitless-sound, or click Continue to use this one.';
        return false;
    }
    return true;
}
